package javafx_inheritance;

import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.layout.VBox;

public class ShoppingController {

	@FXML
	private VBox productsBox;

	@FXML
	private Label totalLbl;

	public void loadProducts() {
		//Make 5 products with a real, unique image URL for each product
		Product apple = new Product("Apples", 1.99, "https://png.pngtree.com/png-vector/20240205/ourlarge/pngtree-group-of-red-apple-fruits-png-image_11625188.png");
		Product banana = new Product("Bananas", 0.59, "https://images.immediate.co.uk/production/volatile/sites/30/2017/01/Bunch-of-bananas-67e91d5.jpg?quality=90&resize=440,400");
		Product carrot = new Product("Carrots", 2.49, "https://png.pngtree.com/png-vector/20240129/ourlarge/pngtree-carrots-with-leaves-png-image_11511904.png");
		Product doughnut = new Product("Doughnuts", 1.20, "data:image/jpeg;base64,");
		Product eggplant = new Product("Eggplants", 3.99, "data:image/jpeg;base64,");

		//Make ProductView objects for each product
		ProductView appleView = new ProductView(apple, totalLbl);
		ProductView bananaView = new ProductView(banana, totalLbl);
		ProductView carrotView = new ProductView(carrot, totalLbl);
		ProductView doughnutView = new ProductView(doughnut, totalLbl);
		ProductView eggplantView = new ProductView(eggplant, totalLbl);

		//Add ProductView objects to the VBox
		productsBox.getChildren().clear();
		productsBox.getChildren().addAll(appleView, bananaView, carrotView, doughnutView, eggplantView);
	}

}
